// SuckCLexerInit initializes any static state used to implement SuckCLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewSuckCLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func SuckCLexerInit() {
	staticData := &SuckCLexerLexerStaticData
	staticData.once.Do(suckclexerLexerInit)
}

// NewSuckCLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewSuckCLexer(input antlr.CharStream) *SuckCLexer {
	SuckCLexerInit()
	l := new(SuckCLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &SuckCLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "SuckCLexer.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

